(() => {
  const cards = [...document.querySelectorAll('[class*="wCourseSearch__Result"], [class*="CourseCard"], article')];
  // Fallback: parse by trainer links + company
  const trainers = [...document.querySelectorAll('a[href*="/trainer-search/trainer/"]')].map(a=>a.textContent.trim());
