(() => {
  // find the chip/pill for Country: Canada and click its remove control
  const nodes = [...document.querySelectorAll('*')].filter(e=>e.children.length<=3 && /Country:\s*Canada/i.test(e.textContent) && e.offsetParent);
  // pick the smallest matching element
  nodes.sort((a,b)=>a.textContent.length-b.textContent.length);
  const chip = nodes[0];
  if(!chip) return 'no chip';
  // find a button/svg/x inside or sibling
  let btn = chip.querySelector('button, svg, [class*="close"], [class*="remove"], [class*="clear"]');
  if(!btn){ // maybe the chip itself or its parent holds the x
    const parent = chip.closest('[class*="chip"],[class*="pill"],[class*="tag"],li,div');
    btn = parent && parent.querySelector('button, svg');
  }
  (btn||chip).click();
  return {clicked: (btn||chip).tagName, chipText: chip.textContent.trim()};
})();

