(() => {
  // Grab detail links as card anchors, then read each card's text block
  const cards = [...document.querySelectorAll('a[href*="/courses/"]')]
    .map(a=>a.closest('[class*="Result"], article, li, div'))
    .filter(Boolean);
  // Dedup card containers
  const seen = new Set(); const uniq = [];
  cards.forEach(c=>{ if(!seen.has(c)){ seen.add(c); uniq.push(c);} });
  const out = uniq.map(c=>{
    const t = c.innerText.replace(/\s+\n/g,'\n');
    // extract date + timezone + language + trainer
    const dateM = t.match(/([A-Z][a-z]{2,3}\s+[A-Z][a-z]{2}\s+\d{1,2}(?:\s*-\s*\d{1,2})?,\s*20\d\d)/);
    const tzM = t.match(/(\d{1,2}:\d{2}\s*[AP]M\s*[A-Z]{2,4})/);
    return {text: t.slice(0,200)};
  });
  return {n: out.length, sample: out.slice(0,3)};
})();

